script:
let allTasks = [];
let allTenders = [];
let currentTaskId = null;
let projects = [];
let currentUser = null;

function initializeDashboard() {
    if (typeof frappe !== 'undefined' && frappe.session && frappe.session.user) {
        currentUser = frappe.session.user;
        const userFilterContainer = root_element.querySelector('.user-filter');
        if (userFilterContainer) {
            userFilterContainer.remove();
        }
    }

    loadProjects();

    const taskProgress = root_element.querySelector('#taskProgress');
    const updateProgress = root_element.querySelector('#updateProgress');

    if (taskProgress) {
        taskProgress.addEventListener('input', function() {
            const progressValue = root_element.querySelector('#progressValue');
            if (progressValue) progressValue.textContent = this.value + '%';
        });
    }

    if (updateProgress) {
        updateProgress.addEventListener('input', function() {
            const updateProgressValue = root_element.querySelector('#updateProgressValue');
            if (updateProgressValue) updateProgressValue.textContent = this.value + '%';
        });
    }

    initializeTabs();
    attachEventListeners();
}

function setupSearchableDropdown(config) {
    const { inputId, hiddenId, optionsId, clearBtnId, getItems, onSelect, onClear, formatLabel, formatValue } = config;

    const input = root_element.querySelector('#' + inputId);
    const hidden = root_element.querySelector('#' + hiddenId);
    const optionsContainer = root_element.querySelector('#' + optionsId);
    const clearBtn = clearBtnId ? root_element.querySelector('#' + clearBtnId) : null;

    if (!input || !hidden || !optionsContainer) return;

    let items = [];
    let highlightedIndex = -1;

    function toggleClearBtn() {
        if (!clearBtn) return;
        clearBtn.style.display = hidden.value ? 'block' : 'none';
    }

    function renderOptions(filterText = '') {
        items = getItems();
        const filtered = items.filter(item =>
            formatLabel(item).toLowerCase().includes(filterText.toLowerCase())
        );

        optionsContainer.innerHTML = '';
        highlightedIndex = -1;

        const allOption = document.createElement('div');
        allOption.className = 'searchable-option';
        allOption.textContent = input.placeholder;
        allOption.onclick = () => selectItem(null);
        optionsContainer.appendChild(allOption);

        if (filtered.length === 0) {
            const noResults = document.createElement('div');
            noResults.className = 'searchable-option no-results';
            noResults.textContent = 'No matches found';
            optionsContainer.appendChild(noResults);
            return;
        }

        filtered.forEach(item => {
            const opt = document.createElement('div');
            opt.className = 'searchable-option';
            opt.textContent = formatLabel(item);
            opt.onclick = () => selectItem(item);
            optionsContainer.appendChild(opt);
        });
    }

    function selectItem(item) {
        if (item === null) {
            hidden.value = '';
            input.value = '';
        } else {
            hidden.value = formatValue(item);
            input.value = formatLabel(item);
        }
        optionsContainer.classList.remove('show');
        toggleClearBtn();
        onSelect(hidden.value);
    }

    function formatCurrentLabel() {
        const match = items.find(i => formatValue(i) === hidden.value);
        return match ? formatLabel(match) : '';
    }

    input.addEventListener('focus', (e) => {
        e.stopPropagation();
        renderOptions(input.value === formatCurrentLabel() ? '' : input.value);
        optionsContainer.classList.add('show');
    });

    input.addEventListener('click', (e) => {
        e.stopPropagation();
        renderOptions(input.value === formatCurrentLabel() ? '' : input.value);
        optionsContainer.classList.add('show');
    });

    input.addEventListener('input', (e) => {
        e.stopPropagation();
        renderOptions(input.value);
        optionsContainer.classList.add('show');
    });

    optionsContainer.addEventListener('mousedown', (e) => {
        e.preventDefault();
    });

    document.addEventListener('mousedown', (e) => {
        const path = e.composedPath ? e.composedPath() : [e.target];
        if (!path.includes(input) && !path.includes(optionsContainer) && (!clearBtn || !path.includes(clearBtn))) {
            optionsContainer.classList.remove('show');
        }
    });

    input.addEventListener('keydown', (e) => {
        const opts = optionsContainer.querySelectorAll('.searchable-option:not(.no-results)');
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            highlightedIndex = Math.min(highlightedIndex + 1, opts.length - 1);
            updateHighlight(opts);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            highlightedIndex = Math.max(highlightedIndex - 1, 0);
            updateHighlight(opts);
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (highlightedIndex >= 0 && opts[highlightedIndex]) {
                opts[highlightedIndex].click();
            }
        } else if (e.key === 'Escape') {
            optionsContainer.classList.remove('show');
        }
    });

    function updateHighlight(opts) {
        opts.forEach(o => o.classList.remove('highlighted'));
        if (opts[highlightedIndex]) {
            opts[highlightedIndex].classList.add('highlighted');
            opts[highlightedIndex].scrollIntoView({ block: 'nearest' });
        }
    }

    if (clearBtn) {
        clearBtn.addEventListener('mousedown', (e) => {
            e.preventDefault(); // don't blur input weirdly
        });
        clearBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            hidden.value = '';
            input.value = '';
            optionsContainer.classList.remove('show');
            toggleClearBtn();
            if (onClear) onClear();
            else onSelect('');
        });
    }

    toggleClearBtn();

    return {
        refresh: () => { renderOptions(input.value); toggleClearBtn(); }
    };
}

function initializeTabs() {
    const tabLinks = root_element.querySelectorAll('.nav-tabs .nav-link');
    tabLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();

            tabLinks.forEach(tab => {
                tab.classList.remove('active');
                const tabPane = root_element.querySelector(tab.getAttribute('href'));
                if (tabPane) {
                    tabPane.classList.remove('active');
                }
            });

            this.classList.add('active');
            const tabPane = root_element.querySelector(this.getAttribute('href'));
            if (tabPane) {
                tabPane.classList.add('active');
            }

            if (this.getAttribute('href') === '#tendersTab') {
                loadTenders();
            }
        });
    });
}

function attachEventListeners() {
    const refreshBtn = root_element.querySelector('.header-actions .btn-primary');
    if (refreshBtn) {
        refreshBtn.onclick = refreshDashboard;
    }


    const searchTender = root_element.querySelector('#searchTender');
        if (searchTender && searchTender.tagName === 'SELECT') {
            searchTender.onchange = searchTenders;
        }

    const closeButtons = root_element.querySelectorAll('[data-dismiss="modal"], .close');
    closeButtons.forEach(btn => {
        btn.onclick = function() {
            const modal = this.closest('.modal');
            if (modal) modal.style.display = 'none';
        };
    });
}

function loadProjects() {
    if (typeof frappe !== 'undefined' && frappe.call) {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Project',
                fields: ['name', 'project_name', 'status'],
                limit: 0,
                order_by: 'project_name'
            },
            callback: function(r) {
                if (r.message) {
                    projects = r.message;
                    populateProjectDropdowns();
                    const projectFilter = root_element.querySelector('#projectFilter');
                    if (projectFilter) {
                        loadTasks(projectFilter.value);
                    } else {
                        loadTasks('');
                    }
                }
            }
        });
    }
}

let projectDropdownCtrl = null;
let taskDropdownCtrl = null;

function populateProjectDropdowns() {
    const taskProject = root_element.querySelector('#taskProject');

    if (taskProject) {
        taskProject.innerHTML = '<option value="">Select Project</option>';
        projects.forEach(project => {
            const option = document.createElement('option');
            option.value = project.name;
            option.textContent = project.project_name || project.name;
            taskProject.appendChild(option);
        });
    }

    if (!projectDropdownCtrl) {
        projectDropdownCtrl = setupSearchableDropdown({
            inputId: 'projectFilterInput',
            hiddenId: 'projectFilter',
            optionsId: 'projectFilterOptions',
            clearBtnId: 'projectFilterClear',
            getItems: () => projects,
            formatLabel: (p) => (p.project_name || p.name) + (p.status ? ` (${p.status})` : ''),
            formatValue: (p) => p.name,
            onSelect: (value) => loadTasks(value),
            onClear: () => refreshDashboard()   // reset to All Projects + refresh
        });
    } else {
        projectDropdownCtrl.refresh();
    }
}


function loadTasks(projectFilter = '') {
    const tasksLoading = root_element.querySelector('#tasksLoading');
    const tasksList = root_element.querySelector('#tasksList');

    if (tasksLoading) tasksLoading.style.display = 'block';
    if (tasksList) tasksList.innerHTML = '';

    let filters = {};
    if (projectFilter) {
        filters['project'] = projectFilter;
    }

    if (typeof frappe !== 'undefined' && frappe.call) {
        frappe.call({
            method: 'altor_project.events.task.get_my_tasks',
            args: {
                filters: filters
            },
            callback: function(r) {
                if (r.message) {
                    allTasks = r.message;
                } else {
                    allTasks = [];
                }
                renderTasks();
                updateStats();
                populateTaskSearchDropdown();
                if (tasksLoading) tasksLoading.style.display = 'none';
            },
            error: function() {
                allTasks = [];
                renderTasks();
                updateStats();
                if (tasksLoading) tasksLoading.style.display = 'none';
            }
        });
    } else {
        if (tasksLoading) tasksLoading.style.display = 'none';
        allTasks = [];
        renderTasks();
        updateStats();
    }
}

function populateTaskSearchDropdown() {
    if (!taskDropdownCtrl) {
        taskDropdownCtrl = setupSearchableDropdown({
            inputId: 'searchTaskInput',
            hiddenId: 'searchTask',
            optionsId: 'searchTaskOptions',
            clearBtnId: 'searchTaskClear',
            getItems: () => allTasks,
            formatLabel: (t) => `${t.subject || 'Untitled Task'} - ${t.status || 'Open'} (${t.progress || 0}%)`,
            formatValue: (t) => t.name,
            onSelect: () => searchTasks(),
            onClear: () => searchTasks()   // resets to "All Tasks" view, no need to refetch
        });
    } else {
        taskDropdownCtrl.refresh();
    }
}
function renderTasks() {
    const tasksList = root_element.querySelector('#tasksList');
    if (!tasksList) return;

    tasksList.innerHTML = '';

    if (allTasks.length === 0) {
        const projectFilter = root_element.querySelector('#projectFilter');
        const selectedProject = projectFilter ? projectFilter.value : '';

        let message = 'No tasks found';
        if (currentUser) {
            message = 'No tasks assigned to you';
            if (selectedProject) {
                const project = projects.find(p => p.name === selectedProject);
                const projectName = project ? (project.project_name || project.name) : selectedProject;
                message = `No tasks assigned to you in project: ${projectName}`;
            }
        } else if (selectedProject) {
            const project = projects.find(p => p.name === selectedProject);
            const projectName = project ? (project.project_name || project.name) : selectedProject;
            message = `No tasks found for project: ${projectName}`;
        }

        tasksList.innerHTML = `
            <div class="text-center" style="padding: 40px; color: #7f8c8d;">
                <i class="fa fa-tasks fa-3x" style="opacity: 0.5; margin-bottom: 15px;"></i>
                <p>${message}</p>
                <button class="btn btn-primary btn-sm create-first-task-btn">
                    <i class="fa fa-plus"></i> Create New Task
                </button>
            </div>
        `;

        const newTaskBtn = tasksList.querySelector('.create-first-task-btn');
        if (newTaskBtn) {
            newTaskBtn.onclick = showNewTaskModal;
        }
        return;
    }

    const parentTasks = allTasks.filter(task => !task.parent_task);
    const childTasks = allTasks.filter(task => task.parent_task);

    const parentTaskMap = {};
    parentTasks.forEach(parent => {
        parentTaskMap[parent.name] = parent;
    });

    const childrenByParent = {};
    childTasks.forEach(child => {
        if (!childrenByParent[child.parent_task]) {
            childrenByParent[child.parent_task] = [];
        }
        childrenByParent[child.parent_task].push(child);
    });

    const collapsibleContainer = document.createElement('div');
    collapsibleContainer.className = 'collapsible-tasks-container';

    parentTasks.forEach(parent => {
        const children = childrenByParent[parent.name] || [];
        const parentElement = createCollapsibleTaskElement(parent, children);
        collapsibleContainer.appendChild(parentElement);
    });

    const orphanTasks = allTasks.filter(task => !task.parent_task && !task.is_group && !parentTaskMap[task.name]);
    if (orphanTasks.length > 0) {
        const separator = document.createElement('div');
        separator.className = 'task-separator';
        separator.innerHTML = '<hr style="border-color: #eee; margin: 20px 0;"><p style="color: #7f8c8d; font-size: 12px;">Independent Tasks</p>';
        collapsibleContainer.appendChild(separator);

        orphanTasks.forEach(task => {
            const taskElement = createTaskElementWithoutChildren(task);
            collapsibleContainer.appendChild(taskElement);
        });
    }

    tasksList.appendChild(collapsibleContainer);
}

function createCollapsibleTaskElement(parent, children) {
    const progress = parseInt(parent.progress) || 0;
    const progressColor = getProgressColor(progress);
    const status = parent.status || 'Open';
    const statusClass = `status-${status.toLowerCase().replace(/ /g, '-')}`;
    const hasChildren = children.length > 0;

    const parentDiv = document.createElement('div');
    parentDiv.className = 'collapsible-parent-task';
    parentDiv.dataset.taskId = parent.name;
    parentDiv.dataset.taskName = parent.subject || 'Untitled Task';
    parentDiv.dataset.taskStatus = status;
    parentDiv.dataset.taskProject = parent.project || '';

    const projectName = parent.project ? getProjectName(parent.project) : 'No Project';

    const startDate = parent.exp_start_date ? formatDate(parent.exp_start_date) : 'Not set';
    const endDate = parent.exp_end_date ? formatDate(parent.exp_end_date) : 'Not set';

    parentDiv.innerHTML = `
        <div class="parent-task-header">
            <div class="parent-task-main">
                <button class="collapse-toggle-btn" ${hasChildren ? '' : 'disabled'} style="background: none; border: none; cursor: ${hasChildren ? 'pointer' : 'default'};">
                    <i class="fa fa-chevron-right collapse-icon"></i>
                </button>
                <div class="parent-task-content">
                    <div class="parent-task-title">
                        <span class="parent-task-subject-link" onclick="openTask('${parent.name}')">
                            ${escapeHtml(parent.subject || 'Untitled Task')}
                        </span>
                        <span class="parent-task-type-label">Parent (${children.length} child${children.length !== 1 ? 'ren' : ''})</span>
                        <span class="parent-task-project">${escapeHtml(projectName)}</span>
                        <span class="status-badge ${statusClass}">${escapeHtml(status)}</span>
                    </div>
                    <div class="parent-task-details">
                        <div class="parent-task-progress">
                            <small>Progress: ${progress}%</small>
                            <div class="progress-bar">
                                <div class="progress-fill" style="width: ${progress}%; background: ${progressColor};"></div>
                            </div>
                        </div>
                        <div class="parent-task-dates">
                            <small><i class="fa fa-calendar"></i> Start: ${startDate}</small>
                            <small style="margin-left: 15px;"><i class="fa fa-calendar-check-o"></i> End: ${endDate}</small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        ${hasChildren ? '<div class="child-tasks-container" style="display: none;"></div>' : ''}
    `;

    if (hasChildren) {
        const childContainer = parentDiv.querySelector('.child-tasks-container');
        children.forEach(child => {
            const childElement = createChildTaskElementForCollapsible(child);
            childContainer.appendChild(childElement);
        });
    }

    const collapseToggle = parentDiv.querySelector('.collapse-toggle-btn');

    if (collapseToggle && hasChildren) {
        collapseToggle.onclick = function(e) {
            e.stopPropagation();
            const childContainer = parentDiv.querySelector('.child-tasks-container');
            const collapseIcon = this.querySelector('.collapse-icon');

            if (childContainer.style.display === 'none') {
                childContainer.style.display = 'block';
                collapseIcon.classList.remove('fa-chevron-right');
                collapseIcon.classList.add('fa-chevron-down');
                parentDiv.classList.add('expanded');
            } else {
                childContainer.style.display = 'none';
                collapseIcon.classList.remove('fa-chevron-down');
                collapseIcon.classList.add('fa-chevron-right');
                parentDiv.classList.remove('expanded');
            }
        };
    }

    return parentDiv;
}

function createChildTaskElementForCollapsible(child) {
    const progress = parseInt(child.progress) || 0;
    const progressColor = getProgressColor(progress);
    const status = child.status || 'Open';
    const statusClass = `status-${status.toLowerCase().replace(/ /g, '-')}`;

    const childDiv = document.createElement('div');
    childDiv.className = 'collapsible-child-task';
    childDiv.dataset.taskId = child.name;
    childDiv.dataset.taskName = child.subject || 'Untitled Task';
    childDiv.dataset.taskStatus = status;
    childDiv.dataset.taskProject = child.project || '';

    const projectName = child.project ? getProjectName(child.project) : 'No Project';

    const startDate = child.exp_start_date ? formatDate(child.exp_start_date) : 'Not set';
    const endDate = child.exp_end_date ? formatDate(child.exp_end_date) : 'Not set';

    childDiv.innerHTML = `
        <div class="child-task-content">
            <div class="child-task-indicator">
                <i class="fa fa-level-up fa-rotate-90" style="color: #95a5a6; margin-right: 10px;"></i>
            </div>
            <div class="child-task-details">
                <div class="child-task-header">
                    <span class="child-task-subject-link" onclick="openTask('${child.name}')">
                        ${escapeHtml(child.subject || 'Untitled Task')}
                    </span>
                    <span class="child-task-type-label">Child Task</span>
                    <span class="child-task-project">${escapeHtml(projectName)}</span>
                    <span class="status-badge ${statusClass}">${escapeHtml(status)}</span>
                </div>
                <div class="child-task-body">
                    <div class="child-task-progress">
                        <small>Progress: ${progress}%</small>
                        <div class="progress-bar">
                            <div class="progress-fill" style="width: ${progress}%; background: ${progressColor};"></div>
                        </div>
                    </div>
                    <div class="child-task-actions">
                        <button class="btn btn-xs btn-outline-primary update-progress-btn">
                            <i class="fa fa-edit"></i> Update
                        </button>
                    </div>
                </div>
                <div class="child-task-dates">
                    <small><i class="fa fa-calendar"></i> Start: ${startDate}</small>
                    <small style="margin-left: 15px;"><i class="fa fa-calendar-check-o"></i> End: ${endDate}</small>
                </div>
                ${child.description ? `
                    <div class="child-task-description">
                        <p>${escapeHtml(child.description)}</p>
                    </div>
                ` : ''}
            </div>
        </div>
    `;

    const updateBtn = childDiv.querySelector('.update-progress-btn');
    if (updateBtn) {
        updateBtn.onclick = function(e) {
            e.stopPropagation();
            editTaskProgress(child.name);
        };
    }

    return childDiv;
}

function createTaskElementWithoutChildren(task) {
    const progress = parseInt(task.progress) || 0;
    const progressColor = getProgressColor(progress);
    const status = task.status || 'Open';
    const statusClass = `status-${status.toLowerCase().replace(/ /g, '-')}`;

    const taskDiv = document.createElement('div');
    taskDiv.className = 'independent-task';
    taskDiv.dataset.taskId = task.name;
    taskDiv.dataset.taskName = task.subject || 'Untitled Task';
    taskDiv.dataset.taskStatus = status;
    taskDiv.dataset.taskProject = task.project || '';

    const projectName = task.project ? getProjectName(task.project) : 'No Project';

    const startDate = task.exp_start_date ? formatDate(task.exp_start_date) : 'Not set';
    const endDate = task.exp_end_date ? formatDate(task.exp_end_date) : 'Not set';

    taskDiv.innerHTML = `
        <div class="independent-task-content">
            <div class="independent-task-header">
                <span class="task-subject-link" onclick="openTask('${task.name}')">
                    ${escapeHtml(task.subject || 'Untitled Task')}
                </span>
                <span class="task-type-label independent-label">Task</span>
                <span class="task-project">${escapeHtml(projectName)}</span>
                <span class="status-badge ${statusClass}">${escapeHtml(status)}</span>
            </div>
            <div class="independent-task-body">
                <div class="task-progress">
                    <small>Progress: ${progress}%</small>
                    <div class="progress-bar">
                        <div class="progress-fill" style="width: ${progress}%; background: ${progressColor};"></div>
                    </div>
                </div>
                <div class="task-actions">
                    <button class="btn btn-xs btn-outline-primary update-progress-btn">
                        <i class="fa fa-edit"></i> Update
                    </button>
                </div>
                <div class="task-dates">
                    <small><i class="fa fa-calendar"></i> Start: ${startDate}</small>
                    <small style="margin-left: 15px;"><i class="fa fa-calendar-check-o"></i> End: ${endDate}</small>
                </div>
            </div>
        </div>
    `;

    const updateBtn = taskDiv.querySelector('.update-progress-btn');
    if (updateBtn) {
        updateBtn.onclick = function(e) {
            e.stopPropagation();
            editTaskProgress(task.name);
        };
    }

    return taskDiv;
}

function openTask(taskId) {
    if (typeof frappe !== 'undefined' && frappe.set_route) {
        frappe.set_route('Form', 'Task', taskId);
    } else {
        window.open(`/app/task/${taskId}`, '_blank');
    }
}

function searchTasks() {
    const searchHidden = root_element.querySelector('#searchTask');
    if (!searchHidden) return;

    const selectedTaskId = searchHidden.value;

    if (!selectedTaskId) {
        const allTaskElements = root_element.querySelectorAll('.collapsible-parent-task, .independent-task');
        allTaskElements.forEach(taskElement => {
            taskElement.style.display = 'block';
        });
        return;
    }

    const allTaskElements = root_element.querySelectorAll('.collapsible-parent-task, .independent-task');
    allTaskElements.forEach(taskElement => {
        taskElement.style.display = 'none';
    });

    const selectedTaskElement = root_element.querySelector(`[data-task-id="${selectedTaskId}"]`);
    if (selectedTaskElement) {
        selectedTaskElement.style.display = 'block';

        if (selectedTaskElement.classList.contains('collapsible-parent-task')) {
            const collapseToggle = selectedTaskElement.querySelector('.collapse-toggle-btn');
            const childContainer = selectedTaskElement.querySelector('.child-tasks-container');
            const collapseIcon = selectedTaskElement.querySelector('.collapse-icon');

            if (collapseToggle && childContainer && collapseIcon && childContainer.style.display === 'none') {
                childContainer.style.display = 'block';
                collapseIcon.classList.remove('fa-chevron-right');
                collapseIcon.classList.add('fa-chevron-down');
                selectedTaskElement.classList.add('expanded');
            }
        }
    }
}

function formatDate(dateString) {
    if (!dateString) return '';
    try {
        const date = new Date(dateString);
        const day = date.getDate().toString().padStart(2, '0');
        const month = date.toLocaleString('default', { month: 'short' });
        const year = date.getFullYear();
        return `${day}-${month}-${year}`;
    } catch (e) {
        return dateString;
    }
}

function getProgressColor(progress) {
    if (progress >= 80) return '#2ecc71';
    if (progress >= 50) return '#3498db';
    if (progress >= 30) return '#f39c12';
    return '#e74c3c';
}

function getProjectName(projectId) {
    const project = projects.find(p => p.name === projectId);
    return project ? (project.project_name || project.name) : projectId;
}

function updateStats() {
    if (allTasks.length === 0) {
        setElementText('totalTasks', '0');
        setElementText('inProgressTasks', '0');
        setElementText('openTasks', '0');
        setElementText('avgProgress', '0%');
        return;
    }

    const totalTasks = allTasks.length;
    const inProgressTasks = allTasks.filter(t => {
        const status = t.status || 'Open';
        return status === 'Working' || status === 'Pending Review' || status === 'Overdue';
    }).length;
    const openTasks = allTasks.filter(t => (t.status || 'Open') === 'Open').length;
    const avgProgress = Math.round(allTasks.reduce((sum, t) => sum + (parseInt(t.progress) || 0), 0) / totalTasks);

    setElementText('totalTasks', totalTasks.toString());
    setElementText('inProgressTasks', inProgressTasks.toString());
    setElementText('openTasks', openTasks.toString());
    setElementText('avgProgress', avgProgress + '%');
}

function setElementText(id, text) {
    const element = root_element.querySelector('#' + id);
    if (element) {
        element.textContent = text;
    }
}

function showNewTaskModal() {
    if (typeof frappe !== 'undefined' && frappe.ui && frappe.ui.Dialog) {
        const projectFilter = root_element.querySelector('#projectFilter');
        const selectedProject = projectFilter ? projectFilter.value : '';

        const dialog = new frappe.ui.Dialog({
            title: 'New Task',
            fields: [
                {
                    label: 'Subject',
                    fieldname: 'subject',
                    fieldtype: 'Data',
                    reqd: 1
                },
                {
                    label: 'Project',
                    fieldname: 'project',
                    fieldtype: 'Link',
                    options: 'Project',
                    default: selectedProject
                },
                {
                    label: 'Parent Task',
                    fieldname: 'parent_task',
                    fieldtype: 'Link',
                    options: 'Task',
                    get_query: function() {
                        return {
                            filters: {
                                'is_group': 1
                            }
                        };
                    }
                },
                {
                    label: 'Status',
                    fieldname: 'status',
                    fieldtype: 'Select',
                    options: ['Open', 'Working', 'Pending Review', 'Overdue', 'Completed'],
                    default: 'Open'
                },
                {
                    label: 'Progress (%)',
                    fieldname: 'progress',
                    fieldtype: 'Int',
                    default: 0,
                    min: 0,
                    max: 100
                },
                {
                    label: 'Expected Start Date',
                    fieldname: 'exp_start_date',
                    fieldtype: 'Date'
                },
                {
                    label: 'Expected End Date',
                    fieldname: 'exp_end_date',
                    fieldtype: 'Date'
                },
                {
                    label: 'Description',
                    fieldname: 'description',
                    fieldtype: 'Text'
                }
            ],
            primary_action_label: 'Save',
            primary_action: function(values) {
                createNewTask(values);
                dialog.hide();
            }
        });

        dialog.show();
    } else {
        const modal = root_element.querySelector('#taskModal');
        const progressValue = root_element.querySelector('#progressValue');
        const taskProgress = root_element.querySelector('#taskProgress');
        const taskProject = root_element.querySelector('#taskProject');
        const projectFilter = root_element.querySelector('#projectFilter');

        if (modal) {
            modal.style.display = 'block';
            if (progressValue) progressValue.textContent = '0%';
            if (taskProgress) taskProgress.value = 0;

            if (taskProject && projectFilter && projectFilter.value) {
                taskProject.value = projectFilter.value;
            }

            loadParentTasksForModal();
        }
    }
}

function loadParentTasksForModal() {
    const projectFilter = root_element.querySelector('#projectFilter');
    const selectedProject = projectFilter ? projectFilter.value : '';

    if (typeof frappe !== 'undefined' && frappe.call) {
        let filters = { 'is_group': 1 };
        if (selectedProject) {
            filters['project'] = selectedProject;
        }

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Task',
                fields: ['name', 'subject'],
                filters: filters,
                limit: 0
            },
            callback: function(r) {
                if (r.message) {
                    const taskParent = root_element.querySelector('#taskParent');
                    if (taskParent) {
                        taskParent.innerHTML = '<option value="">None (Parent Task)</option>';
                        r.message.forEach(task => {
                            const option = document.createElement('option');
                            option.value = task.name;
                            option.textContent = task.subject || task.name;
                            taskParent.appendChild(option);
                        });
                    }
                }
            }
        });
    }
}

function createNewTask(values) {
    if (typeof frappe !== 'undefined' && frappe.call) {
        frappe.call({
            method: 'frappe.client.insert',
            args: {
                doc: {
                    doctype: 'Task',
                    subject: values.subject,
                    project: values.project || undefined,
                    parent_task: values.parent_task || undefined,
                    status: values.status || 'Open',
                    progress: values.progress || 0,
                    exp_start_date: values.exp_start_date || undefined,
                    exp_end_date: values.exp_end_date || undefined,
                    description: values.description || undefined,
                    is_group: values.parent_task ? 0 : 1
                }
            },
            callback: function(r) {
                if (!r.exc) {
                    if (frappe.show_alert) {
                        frappe.show_alert({
                            message: 'Task created successfully!',
                            indicator: 'green'
                        });
                    }
                    const projectFilter = root_element.querySelector('#projectFilter');
                    if (projectFilter) {
                        loadTasks(projectFilter.value);
                    } else {
                        loadTasks('');
                    }
                }
            }
        });
    }
}

function saveTaskFromForm() {
    const subject = root_element.querySelector('#taskSubject');
    const project = root_element.querySelector('#taskProject');
    const parentTask = root_element.querySelector('#taskParent');
    const status = root_element.querySelector('#taskStatus');
    const progress = root_element.querySelector('#taskProgress');
    const description = root_element.querySelector('#taskDescription');

    if (!subject || !subject.value.trim()) {
        alert('Please enter task subject');
        return;
    }

    createNewTask({
        subject: subject.value.trim(),
        project: project ? project.value : '',
        parent_task: parentTask ? parentTask.value : '',
        status: status ? status.value : 'Open',
        progress: progress ? parseInt(progress.value) : 0,
        description: description ? description.value : ''
    });

    const modal = root_element.querySelector('#taskModal');
    if (modal) modal.style.display = 'none';
}

function editTaskProgress(taskId) {
    currentTaskId = taskId;

    const task = allTasks.find(t => t.name === taskId);
    if (!task) return;

    if (typeof frappe !== 'undefined' && frappe.ui && frappe.ui.Dialog) {
        const dialog = new frappe.ui.Dialog({
            title: 'Update Task Progress',
            fields: [
                {
                    label: 'Subject',
                    fieldname: 'subject',
                    fieldtype: 'Data',
                    default: task.subject || '',
                    read_only: 1
                },
                {
                    label: 'Progress (%)',
                    fieldname: 'progress',
                    fieldtype: 'Int',
                    default: task.progress || 0,
                    min: 0,
                    max: 100
                },
                {
                    label: 'Status',
                    fieldname: 'status',
                    fieldtype: 'Select',
                    options: ['Open', 'Working', 'Pending Review', 'Overdue', 'Completed'],
                    default: task.status || 'Open'
                }
            ],
            primary_action_label: 'Update',
            primary_action: function(values) {
                updateTaskProgressInERP(values.progress, values.status);
                dialog.hide();
            }
        });

        dialog.show();
    } else {
        const modal = root_element.querySelector('#progressModal');
        const updateProgress = root_element.querySelector('#updateProgress');
        const updateProgressValue = root_element.querySelector('#updateProgressValue');
        const updateStatus = root_element.querySelector('#updateStatus');

        if (modal && updateProgress && updateProgressValue && updateStatus) {
            updateProgress.value = task.progress || 0;
            updateProgressValue.textContent = (task.progress || 0) + '%';
            updateStatus.value = task.status || 'Open';
            modal.style.display = 'block';
        }
    }
}

function updateTaskProgressFromForm() {
    const updateProgress = root_element.querySelector('#updateProgress');
    const updateStatus = root_element.querySelector('#updateStatus');

    if (!updateProgress || !updateStatus || !currentTaskId) return;

    const progress = parseInt(updateProgress.value);
    const status = updateStatus.value;

    updateTaskProgressInERP(progress, status);

    const modal = root_element.querySelector('#progressModal');
    if (modal) modal.style.display = 'none';
}

function updateTaskProgressInERP(progress, status) {
    if (!currentTaskId || typeof frappe === 'undefined' || !frappe.call) return;

    frappe.call({
        method: 'frappe.client.set_value',
        args: {
            doctype: 'Task',
            name: currentTaskId,
            fieldname: {
                progress: progress,
                status: status
            }
        },
        callback: function(r) {
            if (!r.exc) {
                if (frappe.show_alert) {
                    frappe.show_alert({
                        message: 'Progress updated successfully!',
                        indicator: 'green'
                    });
                }
                const projectFilter = root_element.querySelector('#projectFilter');
                if (projectFilter) {
                    loadTasks(projectFilter.value);
                } else {
                    loadTasks('');
                }
            }
        }
    });
}

function refreshDashboard() {
    if (typeof frappe !== 'undefined' && frappe.show_alert) {
        frappe.show_alert({
            message: 'Refreshing dashboard...',
            indicator: 'blue'
        });
    }
    loadProjects();
}

function escapeHtml(text) {
    if (typeof frappe !== 'undefined' && frappe.utils && frappe.utils.escape_html) {
        return frappe.utils.escape_html(text);
    }

    if (text === null || text === undefined) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

