.pill.blue { background: color-mix(in srgb, var(--blue) 13%, transparent); color: var(--blue); }
.pill.gray { background: color-mix(in srgb, var(--slate) 15%, transparent); color: var(--slate); }
.mini { display: inline-block; width: 80px; height: 6px; border-radius: 4px; background: var(--soft); vertical-align: middle; margin-right: 7px; overflow: hidden; position: relative; }
.mini span { position: absolute; left: 0; top: 0; bottom: 0; width: 0; border-radius: 4px; transition: width 1s cubic-bezier(.2, .8, .2, 1); }
.list-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px dashed var(--line); font-size: 12.5px; }
.list-row:last-child { border-bottom: none; }
.list-row.link { cursor: pointer; }
.list-row.link:hover b { color: var(--hero, #2f7ff0); }
.avatar { width: 28px; height: 28px; border-radius: 50%; display: inline-grid; place-items: center; font-size: 11px; font-weight: 700; color: #fff; margin-right: 9px; flex: 0 0 auto; }
.who { display: flex; align-items: center; min-width: 0; }
.who b { font-weight: 600; }

/* ---------- motion ---------- */
.anim { animation: rise .55s cubic-bezier(.2, .8, .2, 1) both; animation-delay: calc(var(--i, 0) * 45ms); }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
