@keyframes pulse { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--c) 55%, transparent); } 70% { box-shadow: 0 0 0 7px transparent; } 100% { box-shadow: 0 0 0 0 transparent; } }
@keyframes shimmer { 0% { background-position: -400px 0; } 100% { background-position: 400px 0; } }
.skel { border-radius: 14px; height: 86px; border: 1px solid var(--line);
    background: linear-gradient(90deg, var(--soft) 0px, var(--card) 120px, var(--soft) 240px); background-size: 800px 100%; animation: shimmer 1.3s infinite linear; }
