.kpi-sub { font-size: 11.5px; color: var(--muted); margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tag { display: inline-flex; align-items: center; gap: 3px; padding: 1px 7px; border-radius: 20px; font-size: 11px; font-weight: 600; }
.tag.up { color: var(--green); background: color-mix(in srgb, var(--green) 12%, transparent); }
.tag.down { color: var(--red); background: color-mix(in srgb, var(--red) 12%, transparent); }
.tag.warn { color: var(--orange); background: color-mix(in srgb, var(--orange) 14%, transparent); }

/* ---------- alert chips ---------- */
.chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.chip { display: inline-flex; align-items: center; gap: 7px; padding: 7px 12px; border-radius: 999px; font-size: 12.5px; font-weight: 500;
    border: 1px solid color-mix(in srgb, var(--c) 30%, transparent); color: color-mix(in srgb, var(--c) 85%, var(--ink));
    background: color-mix(in srgb, var(--c) 9%, transparent); }
.chip b { font-weight: 700; }
.chip .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 0 var(--c); animation: pulse 2s infinite; }
.chip.ok { --c: var(--green); }
.chip.ok .dot { animation: none; }

/* ---------- panels ---------- */
.grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 12px; }
.span-4 { grid-column: span 4; } .span-5 { grid-column: span 5; } .span-6 { grid-column: span 6; }
.span-7 { grid-column: span 7; } .span-8 { grid-column: span 8; } .span-12 { grid-column: span 12; }
.panel { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 16px 18px; min-width: 0; }
.panel-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 12px; }
.panel-head h3 { margin: 0; font-size: 14px; font-weight: 700; }
.panel-head span { font-size: 11.5px; color: var(--muted); }
.empty { color: var(--muted); font-size: 12.5px; padding: 22px 0; text-align: center; }
.empty svg { display: block; margin: 0 auto 6px; opacity: .5; }

/* ---------- feature card (ring + breakdown) ---------- */
.feature { display: flex; gap: 22px; align-items: center; flex-wrap: wrap; }
.ring { position: relative; flex: 0 0 auto; }
.ring svg { transform: rotate(-90deg); display: block; }
.ring-center { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; }
.ring-center b { display: block; font-size: 24px; font-weight: 800; letter-spacing: -.02em; line-height: 1.15; }
.ring-center b span { font-size: inherit; color: inherit; }
.ring-center > div > span { display: block; font-size: 11px; color: var(--muted); margin-top: 2px; }
