.fill.ghost { opacity: .28; }
.hbar.link { cursor: pointer; }
.hbar.link:hover .hbar-name { color: var(--hero, #2f7ff0); }
.legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 11.5px; color: var(--muted); margin-top: 10px; }
