.donut-list { flex: 1; min-width: 150px; font-size: 12.5px; }
.donut-list div { display: flex; justify-content: space-between; gap: 8px; padding: 4px 0; }
.donut-list i { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 7px; }
.donut-list b { font-variant-numeric: tabular-nums; }

/* ---------- column chart ---------- */
.cols { display: flex; align-items: flex-end; gap: 8px; height: 170px; padding-top: 6px; border-bottom: 1px solid var(--line); }
